  "textverstaendnis-bs": {"fach": "textverstaendnis-bs", "name": "Deutsch Textverständnis", "pruefung": "Freiwillige Aufnahmeprüfung in die Sekundarstufe II, Kanton Basel-Stadt", "quelle": "Prüfungsanforderungen Deutsch 2026 (Anhang zu den Richtlinien vom 12. August 2024) sowie die Musterprüfungen März 2021 und März 2022", "punkteTotal": 28, "oberthemen": [{"nr": 1, "katalog": "1", "name": "Sachtexte verstehen", "punkte": 11, "anteil": 39, "beschreibung": "Ein Sachtext oder eine Kolumne, dazu rund fünfzehn Fragen. Der Text ist lang. Man muss nicht jedes Wort verstehen, um ihn zu verstehen.", "unterthemen": [{"code": "1.01", "name": "Einzelne Angaben im Text finden", "lernzielId": "TBS.1.01", "pflichtset": 12}, {"code": "1.02", "name": "Grafiken, Tabellen und Bilder auswerten", "lernzielId": "TBS.1.02", "pflichtset": 12}, {"code": "1.03", "name": "Den Text als Ganzes verstehen", "lernzielId": "TBS.1.03", "pflichtset": 12, "voraussetzungen": ["1.01"]}, {"code": "1.04", "name": "Unbekannte Wörter aus dem Zusammenhang erschliessen", "lernzielId": "TBS.1.04", "pflichtset": 12}, {"code": "1.05", "name": "Aussagen als richtig oder falsch prüfen", "lernzielId": "TBS.1.05", "pflichtset": 12, "voraussetzungen": ["1.01"]}, {"code": "1.06", "name": "Was steht mit Sicherheit im Text?", "lernzielId": "TBS.1.06", "pflichtset": 12, "voraussetzungen": ["1.05"]}]}, {"nr": 2, "katalog": "2", "name": "Literarische Texte verstehen", "punkte": 10, "anteil": 36, "beschreibung": "Eine Erzählung oder ein Ausschnitt daraus. Gefragt wird nach den Figuren und danach, was wirklich dasteht, nicht danach, was man sich denken könnte.", "unterthemen": [{"code": "2.01", "name": "Handlung und Reihenfolge erfassen", "lernzielId": "TBS.2.01", "pflichtset": 12}, {"code": "2.02", "name": "Figuren und ihr Handeln verstehen", "lernzielId": "TBS.2.02", "pflichtset": 12}, {"code": "2.03", "name": "Gefühle und Reaktionen einer Figur belegen", "lernzielId": "TBS.2.03", "pflichtset": 12, "voraussetzungen": ["2.02"]}, {"code": "2.04", "name": "Ort, Zeit und Situation erschliessen", "lernzielId": "TBS.2.04", "pflichtset": 12}, {"code": "2.05", "name": "Aussagen ausschliessen, die nicht zutreffen", "lernzielId": "TBS.2.05", "pflichtset": 12, "voraussetzungen": ["2.02"]}]}, {"nr": 3, "katalog": "3", "name": "Reflexion und Strategien", "punkte": 7, "anteil": 25, "beschreibung": "Die Fragen, die über den Text hinausgehen: Worum geht es? Was für ein Text ist das? Was will er von mir?", "unterthemen": [{"code": "3.01", "name": "Thema und Kernaussage eines Textes", "lernzielId": "TBS.3.01", "pflichtset": 12}, {"code": "3.02", "name": "Textsorte erkennen", "lernzielId": "TBS.3.02", "pflichtset": 12}, {"code": "3.03", "name": "Absicht des Textes erkennen", "lernzielId": "TBS.3.03", "pflichtset": 12, "voraussetzungen": ["3.02"]}, {"code": "3.04", "name": "Das Gelesene beurteilen", "lernzielId": "TBS.3.04", "pflichtset": 12, "voraussetzungen": ["3.01"]}, {"code": "3.05", "name": "Sprachliche Bilder im Text deuten", "lernzielId": "TBS.3.05", "pflichtset": 12}]}]},
