/* =======================================================================
   SCREENS
   ======================================================================= */
const S = {};
/**
 * Ein- oder Mehrzahl, je nach Anzahl.
 *
 * «Prüfung in 1 Tagen» und «noch 1 Monate» sind falsches Deutsch, und sie
 * stehen ausgerechnet dort, wo es am meisten zählt: am Vortag der Prüfung
 * und auf dem Kauf-Screen. Das Projekt verbietet solche Fälle ausdrücklich
 * («die ersten 1 Stunden» ist rechnerisch richtig und trotzdem falsch).
 */
const zahlwort = (n, ein, mehr) => n + ' ' + (Math.abs(n) === 1 ? ein : mehr);

const esc = s => String(s??'').replace(/[&<>"']/g, c =>
  ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

/** Im Aufgabentext hebt «_Wort_» hervor, so kommen die markierten Stellen
 *  aus dem ZAP-Trainer herüber, ohne dass HTML durch die Daten reist. */
/** Aus ⁴⁄₆ wird ein zweizeiliger Bruch.
 *
 *  Läuft auf bereits maskiertem Text, wie `hervor`, und aus demselben
 *  Grund: HTML reist nie durch die Daten. Wer die Zeichenkette ungerendert
 *  sieht, liest immer noch ⁴⁄₆ und nicht «4/6». */
const ZURUECK = {'⁰':'0','¹':'1','²':'2','³':'3','⁴':'4','⁵':'5','⁶':'6','⁷':'7',
                 '⁸':'8','⁹':'9','⁻':'-','₀':'0','₁':'1','₂':'2','₃':'3','₄':'4',
                 '₅':'5','₆':'6','₇':'7','₈':'8','₉':'9','₋':'-'};
const ziffern = t => t.split('').map(c=>ZURUECK[c]||c).join('');
const brueche = h => h.replace(/([⁰¹²³⁴⁵⁶⁷⁸⁹⁻]+)⁄([₀₁₂₃₄₅₆₇₈₉₋]+)/g,
  (_,z,n) => `<span class="bruch"><i>${ziffern(z)}</i><b>${ziffern(n)}</b></span>`);

/** Maskieren UND Brüche setzen. Überall dort zu benutzen, wo Aufgabeninhalt
 *  auf den Bildschirm kommt. Stamm, Optionen, Rückmeldung, Lösungsweg.
 *
 *  NICHT `mathe` nennen: So heisst in `setZiehen` schon eine lokale Variable
 *  für die Mathematik-Templates, und eine Verschattung ist genau die Sorte
 *  Fehler, die erst auffällt, wenn ein Screen leer bleibt. */
const anzeige = s => brueche(esc(s));

const hervor = s => brueche(esc(s).replace(/_([^_\n]+)_/g,
  '<b style="color:var(--ink);font-weight:700">$1</b>'));


/* =======================================================================
   OBERFLÄCHE der neuen Formate. Alles wird angetippt, nichts gezogen —
   auf einem Telefon ist Ziehen mit dem Daumen unzuverlässig.
   ======================================================================= */

/** Eine Tabelle oder ein Zahlenstrahl über der Aufgabe. */
function darstellungHtml(d){
  if(!d || d.typ !== 'tabelle') return '';
  return `<div class="karte mb16" style="padding:12px;overflow-x:auto">
    <table style="border-collapse:collapse;width:100%;font:400 13px 'Nunito Sans'">
     ${d.kopf && d.kopf.length ? `<tr>${d.kopf.map(k=>
       `<th style="text-align:left;padding:6px 10px;border-bottom:1px solid var(--line);
         font:700 11px 'Nunito Sans';color:var(--tan6);text-transform:uppercase;
         letter-spacing:.08em">${esc(k)}</th>`).join('')}</tr>` : ''}
     ${d.zeilen.map(z=>`<tr>${z.map((c,i)=>
       `<td style="padding:6px 10px;border-bottom:1px solid var(--line);
         ${i===0?"color:var(--ink5)":"font:600 14px Bitter,Georgia,serif"}">${esc(c)}</td>`).join('')}</tr>`).join('')}
    </table></div>`;
}

/** Mehrere Antwortfelder. Jedes trägt sein Etikett. Sonst weiss niemand,
 *  was wohin gehört. */
function mehrfeldHtml(a){
  const L = Z.lauf, w = L.felder || {};
  const fehler = (L.rueckmeldung && L.rueckmeldung.feldFehler) || [];
  return `<div class="mt20">${a.felder.map(f=>`
    <div class="mb12">
     <div class="lb mb8" style="color:var(--ink5)">${esc(f.label)}</div>
     <div class="feld" style="height:54px;${fehler.includes(f.name)
        ? 'border-color:var(--red);background:var(--red1)' : ''}">
      <input type="text" enterkeyhint="next"
       inputmode="${f.loesungWorte||App.kannNegativ(a)?'text':'decimal'}"
       value="${esc(w[f.name]||'')}" placeholder="—"
       oninput="App.feldEingabe('${f.name}', this.value)"
       autocomplete="off" autocapitalize="off" spellcheck="false"
       style="font:600 17px 'Bitter',Georgia,serif">
      ${f.einheit?`<span class="sm" style="color:var(--ink3)">${esc(f.einheit)}</span>`:''}
     </div></div>`).join('')}</div>`;
}

/** Tabelle mit Auswahlspalte: je Zeile genau eine Wortart, ein Fall, eine Zeitform. */
function tabelleHtml(a){
  const L = Z.lauf, g = L.zeilen || {};
  const fehler = (L.rueckmeldung && L.rueckmeldung.zeilenFehler) || [];
  return `<div class="mt20">${a.zeilen.map(z=>`
    <div class="karte mb8" style="padding:12px 14px;${fehler.includes(z.index)
       ? 'border-color:var(--red)' : ''}">
     <div class="h4 mb8">${anzeige(z.text)}</div>
     <div style="display:flex;flex-wrap:wrap;gap:6px">
      ${a.optionen.map(o=>`
       <button onclick="App.zeileWaehlen(${z.index}, '${esc(o.text).replace(/'/g,"\\\\'")}')"
        style="border-radius:8px;padding:5px 10px;cursor:pointer;
        font:600 12px 'Nunito Sans';
        border:1px solid ${g[z.index]===o.text?'var(--ink)':'var(--line)'};
        background:${g[z.index]===o.text?'var(--ink)':'transparent'};
        color:${g[z.index]===o.text?'var(--cream)':'var(--ink)'}">${anzeige(o.text)}</button>`).join('')}
     </div></div>`).join('')}</div>`;
}

/** Koordinatengitter. Vorgaben und Strecken sind gezeichnet, gesetzte Punkte
 *  lassen sich durch nochmaliges Antippen wieder entfernen. */
function gitterHtml(a){
  const G = a.gitter, L = Z.lauf;
  const gesetzt = L.punkte || {};
  const B = 300, R = 14;                       // Bildbreite und Rand
  const spanX = G.xbis - G.xvon, spanY = G.ybis - G.yvon;
  /* Ein Gitter ohne Hoehe ist ein ZAHLENSTRAHL: eine Achse, Teilstriche,
     und man setzt die Marke auf einen Wert. Dieselbe Bedienung wie im
     Koordinatengitter. Ein zweites Antippen nimmt sie zurueck. */
  const strahl = spanY === 0;
  const s = (B - 2*R) / Math.max(spanX, spanY, 1);
  const H = strahl ? 92 : R*2 + spanY * s;
  const X = x => R + (x - G.xvon) * s;
  /* Frueher stand hier `B - R - …`. Das stimmt nur, solange das Gitter so
     hoch ist wie breit; bei einem breiteren Gitter zeichnete es die Punkte
     UNTER den sichtbaren Bereich, und man sah sie schlicht nicht. */
  const Y = y => strahl ? H/2 : H - R - (y - G.yvon) * s;

  let g = '';
  if(strahl){
    g += `<line x1="${X(G.xvon)}" y1="${Y(0)}" x2="${X(G.xbis)}" y2="${Y(0)}"
           stroke="#3A1D0A" stroke-width="1.5"/>`;
    for(let x = G.xvon; x <= G.xbis; x++){
      const gross = (x - G.xvon) % 5 === 0;
      g += `<line x1="${X(x)}" y1="${Y(0)-(gross?7:4)}" x2="${X(x)}" y2="${Y(0)+(gross?7:4)}"
             stroke="#3A1D0A" stroke-width="${gross?1.4:1}"/>`;
      if(gross)
        g += `<text x="${X(x)}" y="${Y(0)+24}" font-size="11" text-anchor="middle"
               font-family="Bitter,serif" fill="#5C3A1E">${x}</text>`;
    }
  } else {
    for(let x = G.xvon; x <= G.xbis; x++)
      g += `<line x1="${X(x)}" y1="${Y(G.yvon)}" x2="${X(x)}" y2="${Y(G.ybis)}"
             stroke="${x===G.xvon?'#3A1D0A':'#EADCC6'}" stroke-width="1"/>`;
    for(let y = G.yvon; y <= G.ybis; y++)
      g += `<line x1="${X(G.xvon)}" y1="${Y(y)}" x2="${X(G.xbis)}" y2="${Y(y)}"
             stroke="${y===G.yvon?'#3A1D0A':'#EADCC6'}" stroke-width="1"/>`;
  }
  G.strecken.forEach(st=>{
    const hilf = st.stil === 'hilfslinie';
    g += `<line x1="${X(st.von[0])}" y1="${Y(st.von[1])}" x2="${X(st.bis[0])}" y2="${Y(st.bis[1])}"
           stroke="${hilf?'#E2231A':'#B0834F'}" stroke-width="${hilf?1.5:2}"
           ${hilf?'stroke-dasharray="5 4"':''}/>`;
  });
  G.vorgabe.forEach(v=>{
    g += `<circle cx="${X(v.x)}" cy="${Y(v.y)}" r="4.5" fill="#B0834F"/>
          <text x="${X(v.x)+7}" y="${Y(v.y)-6}" font-size="11" font-family="Bitter,serif"
           fill="#5C3A1E">${esc(v.text)}</text>`;
  });
  // Trefferflächen: jeder Gitterpunkt ist antippbar.
  for(let x = G.xvon; x <= G.xbis; x++)
    for(let y = G.yvon; y <= G.ybis; y++)
      g += `<circle cx="${X(x)}" cy="${Y(y)}" r="${Math.max(strahl?9:7, s/2.2)}" fill="transparent"
             style="cursor:pointer" onclick="App.gitterTippen(${x},${y})"/>`;
  G.punkte.forEach(p=>{
    const q = gesetzt[p.name]; if(!q) return;
    g += `<circle cx="${X(q[0])}" cy="${Y(q[1])}" r="6" fill="#3A1D0A"/>
          <text x="${X(q[0])+8}" y="${Y(q[1])-7}" font-size="11" font-family="Bitter,serif"
           font-weight="600" fill="#3A1D0A">${esc(p.label)}</text>`;
  });

  const naechster = G.punkte.find(p => !gesetzt[p.name]);
  return `<div class="mt20">
   <div class="bd mb10" style="color:var(--ink5)">${naechster
      ? `Tippe ${strahl ? 'auf dem Zahlenstrahl' : 'im Gitter'} auf die Stelle für <b style="color:var(--ink)">${esc(naechster.label)}</b>`
      : 'Alle Marken gesetzt. Zum Ändern nochmals antippen.'}</div>
   <div class="karte" style="padding:8px;display:flex;justify-content:center">
    <svg viewBox="0 0 ${B} ${H}" style="width:100%;max-width:340px;height:auto"
     role="img" aria-label="${strahl?'Zahlenstrahl':'Koordinatengitter'} zum Antippen">${g}</svg></div>
   <div class="reihe mt10" style="gap:8px;flex-wrap:wrap">
    ${G.punkte.map(p=>`<span class="chip ${gesetzt[p.name]?'an':''}"
      onclick="App.punktLoeschen('${p.name}')" style="cursor:pointer;height:40px;padding:0 14px">
      ${esc(p.label)}${gesetzt[p.name]?` (${gesetzt[p.name][0]} | ${gesetzt[p.name][1]})`:' —'}</span>`).join('')}
   </div></div>`;
}

/** Zuordnen: erst links ein Ziel wählen, dann rechts das passende Ergebnis. */
function zuordnenHtml(a){
  const L = Z.lauf, z = L.zuordnung || {}, offen = L.zuordnenGewaehlt;
  const belegt = new Set(Object.values(z));
  return `<div class="mt20">
   <div class="sm mb10">${offen === undefined
     ? 'Tippe links auf einen Term und dann rechts auf sein Ergebnis.'
     : 'Wähle jetzt rechts das passende Ergebnis.'}</div>
   ${a.paare.map((p,i)=>`
    <div class="karte mb8" style="padding:10px 12px;
      ${offen===i?'border:2px solid var(--ink);padding:9px 11px':''}">
     <div class="reihe" style="gap:10px">
      <button onclick="App.zuordnenZiel(${i})" style="flex:1;text-align:left;border:none;
       background:transparent;cursor:pointer;font:500 15px 'Bitter',Georgia,serif;
       color:var(--ink)">${esc(p.ziel)}</button>
      ${I(ICON.pfeil,16,'none','#A98B66')}
      <div style="flex:1;text-align:right;font:500 15px 'Bitter',Georgia,serif;
       color:${z[i]!==undefined?'var(--ink)':'var(--ink3)'}">
       ${z[i]!==undefined ? esc(a.paare[z[i]].element) : '—'}</div>
     </div></div>`).join('')}
   <div class="eyebrow mt16 mb8">Ergebnisse</div>
   <div style="display:flex;flex-wrap:wrap;gap:6px">
    ${a.mischung.map(k=>`
     <button onclick="App.zuordnenElement(${k})" ${belegt.has(k)?'disabled':''}
      style="border-radius:9px;min-height:44px;padding:0 14px;cursor:pointer;
      font:500 15px 'Bitter',Georgia,serif;opacity:${belegt.has(k)?.35:1};
      border:1px solid var(--tan3);background:var(--card);color:var(--ink)">
      ${esc(a.paare[k].element)}</button>`).join('')}
   </div></div>`;
}

/** Sortieren: der Reihe nach antippen. Die Nummer zeigt den Platz. */
function sortierenHtml(a){
  const L = Z.lauf, r = L.reihenfolge || [];
  return `<div class="mt20">
   <div class="bd mb10" style="color:var(--ink5)">Tippe die Elemente in der richtigen Reihenfolge an —
    das kleinste zuerst. ${r.length} von ${a.elemente.length} gesetzt.</div>
   ${a.mischung.map(k=>{
     const platz = r.indexOf(k);
     return `<button onclick="App.sortierenTippen(${k})" class="wahl mb8 ${platz>=0?'an':''}"
      style="display:flex;align-items:center;gap:12px">
      <span style="width:26px;height:26px;border-radius:50%;flex:none;display:flex;
       align-items:center;justify-content:center;font:700 12px 'Nunito Sans';
       background:${platz>=0?'var(--ink)':'var(--tan1)'};
       color:${platz>=0?'var(--cream)':'var(--tan6)'}">${platz>=0?platz+1:'·'}</span>
      <span style="flex:1;text-align:left;font:500 15px 'Bitter',Georgia,serif">
       ${esc(a.elemente[k].text)}</span></button>`;
   }).join('')}
   ${r.length ? `<button class="btn bt" onclick="App.sortierenZuruecksetzen()">Reihenfolge löschen</button>` : ''}
  </div>`;
}

/** Wertetabelle: Paare eintragen, so viele wie nötig. */
function wertetabelleHtml(a){
  const L = Z.lauf, p = L.paare || [];
  const sp = a.wertetabelle.spalten;
  // Eine Zeile mehr, als es Lösungen gibt, so merkt niemand an der Anzahl
  // Zeilen, wie viele Paare gesucht sind.
  const zeilen = Math.max(p.length + 1, a.wertetabelle.paare.length + 1);
  const voll = p.filter(q => q && q[0] !== null && q[1] !== null).length;
  return `<div class="mt20">
   <div class="wtabelle">
    <div class="wt-kopf">
     <div class="wt-nr"></div>
     ${sp.map(s=>`<div>${esc(s.kopf)}</div>`).join('')}
    </div>
    ${Array.from({length: zeilen}, (_, i) => `
     <div class="wt-zeile">
      <div class="wt-nr">${i+1}</div>
      ${sp.map((s,k)=>`
       <input type="text" enterkeyhint="next"
        inputmode="${App.kannNegativ(a)?'text':'numeric'}" class="wt-feld"
        value="${(p[i]&&p[i][k]!==null)?p[i][k]:''}"
        aria-label="Zeile ${i+1}, ${esc(s.kopf)}"
        oninput="App.paarEingabe(${i},${k},this.value)" placeholder="—">`).join('')}
     </div>`).join('')}
   </div>
   <div class="sm mt10">${voll} ${voll === 1 ? 'Zeile' : 'Zeilen'} ausgefüllt.
    Leere Zeilen werden nicht gewertet.</div>
  </div>`;
}

/** Felder färben: ein Raster, jedes Feld schaltbar. */
function faerbenHtml(a){
  const L = Z.lauf, an = L.felder2 || [];
  const R = a.raster, gr = Math.min(46, 260 / R.spalten);
  let g = '';
  for(let i = 0; i < R.spalten * R.zeilen; i++)
    g += `<button onclick="App.feldFaerben(${i})" style="width:${gr}px;height:${gr}px;
      border:1px solid ${an.includes(i)?'var(--ink)':'var(--line)'};
      background:${an.includes(i)?'var(--tan)':'var(--card)'};
      border-radius:4px;cursor:pointer"></button>`;
  return `<div class="mt20">
   <div class="bd mb10" style="color:var(--ink5)">Tippe die Felder an, die gefärbt werden sollen.
    ${an.length} gefärbt.</div>
   <div class="karte" style="padding:12px;display:flex;justify-content:center">
    <div style="display:grid;grid-template-columns:repeat(${R.spalten}, ${gr}px);gap:4px">
     ${g}</div></div></div>`;
}

/* --- gemeinsame Bausteine --------------------------------------------- */
const appbar = (titel, links='', rechts='') => `
 <div class="safe"></div>
 <div class="appbar">${links}<h2>${esc(titel)}</h2><div style="flex:1"></div>${rechts}</div>`;

/** Wohin ein Rück- oder Schliessknopf führt, in Worten, für Vorlese-
 *  programme und als Tooltip. Ein «X» allein sagt niemandem, wo er landet. */
const ZIELNAME = {
  Lernen:'zur Übersicht', Lernpfad:'zum Lernpfad', Selbsttest:'zum Selbsttest',
  Fortschritt:'zum Fortschritt', Einstellungen:'zu den Einstellungen',
  Anmeldung:'zur Anmeldung', KantonWahl:'zur Kantonswahl',
  SchulWahl:'zur Schulwahl', PruefungTermin:'zum Prüfungstermin',
  Diagnosetest:'zur Standortbestimmung', Fehlerarchiv:'zu deinen Fehlern',
  AufsatzThemen:'zu den Aufsatzthemen', AufsatzSchreiben:'zum Aufsatz',
  Plus:'zu StudySwiss Plus', Profil:'zum Profil',
};
const zielName = ziel =>
  ZIELNAME[ziel] || (ziel.startsWith('Fach:') ? 'zu den Themen des Fachs' : 'zurück');

const zurueckKnopf = ziel =>
  `<button class="ibtn" aria-label="Zurück ${zielName(ziel)}"
    title="Zurück ${zielName(ziel)}"
    onclick="App.geh('${ziel}')">${I(ICON.zurueck,22)}</button>`;
const schliessKnopf = ziel =>
  `<button class="ibtn" aria-label="Schliessen und ${zielName(ziel)}"
    title="Schliessen und ${zielName(ziel)}"
    onclick="App.geh('${ziel}')">${I(ICON.x,22)}</button>`;

const tabbar = aktiv => {
  const t = [['Lernen','lernen','Lernen'],['Lernpfad','pfad','Lernpfad'],
             ['Selbsttest','test','Selbsttest'],['Fortschritt','chart','Fortschritt'],
             ['Einstellungen','zahn','Einstellungen']];
  return `<div class="tabbar">${t.map(([name,ic,ziel])=>`
    <button class="tab ${aktiv===name?'on':''}" onclick="App.geh('${ziel}')">
      ${I(ICON[ic],22,'none', aktiv===name?'#3A1D0A':'#A98B66', aktiv===name?1.9:1.6)}
      <span>${name}</span></button>`).join('')}</div>`;
};

